constexpr std::uint64_t packEpochValue(
    std::uint32_t epoch,
    std::uint32_t value) noexcept
{
    return (static_cast<std::uint64_t>(epoch) << 32)
        | static_cast<std::uint64_t>(value);
}

constexpr std::uint32_t unpackEpoch(
    std::uint64_t packed) noexcept
{
    return static_cast<std::uint32_t>(packed >> 32);
}

constexpr std::uint32_t unpackValue(
    std::uint64_t packed) noexcept
{
    return static_cast<std::uint32_t>(packed & 0xffffffffULL);
}

void incrementEpochCounter(
    std::atomic<juce::uint64>& counter,
    std::uint32_t epoch) noexcept
{
    const auto previous = counter.load(std::memory_order_relaxed);
    if (unpackEpoch(previous) != epoch)
    {
        counter.store(packEpochValue(epoch, 1), std::memory_order_relaxed);
        return;
    }

    const auto previousValue = unpackValue(previous);
    const auto nextValue = previousValue < std::numeric_limits<std::uint32_t>::max()
        ? previousValue + 1
        : previousValue;
    counter.store(packEpochValue(epoch, nextValue), std::memory_order_relaxed);
}

void updateEpochMaximum(
    std::atomic<juce::uint64>& maximum,
    std::uint32_t epoch,
    std::uint32_t value) noexcept
{
    const auto previous = maximum.load(std::memory_order_relaxed);
    if (unpackEpoch(previous) != epoch || value > unpackValue(previous))
        maximum.store(packEpochValue(epoch, value), std::memory_order_relaxed);
}

void addMonoHardwareInputToStereoProcessingPath(
    juce::AudioBuffer<float>& processingBuffer,
    const float* monoInput,
    int numSamples) noexcept
{
    const int samplesToAdd = juce::jlimit(
        0,
        processingBuffer.getNumSamples(),
        numSamples);
    if (monoInput == nullptr
        || processingBuffer.getNumChannels() < 2
        || samplesToAdd <= 0)
    {
        return;
    }

    // Channel 0 already contains the selected hardware input. Add only that
    // known mono contribution to channel 1 so the realtime FX path receives a
    // centred dual-mono dry source without copying over stereo clips or sends.
    juce::FloatVectorOperations::add(
        processingBuffer.getWritePointer(1),
        monoInput,
        samplesToAdd);
}

class ScopedRealtimeSnapshotReader final
{
public:
    explicit ScopedRealtimeSnapshotReader(
        std::atomic<std::uint32_t>& readersToUse) noexcept
        : readers(readersToUse)
    {
        readers.fetch_add(1, std::memory_order_seq_cst);
    }

    ~ScopedRealtimeSnapshotReader()
    {
        readers.fetch_sub(1, std::memory_order_seq_cst);
    }

    ScopedRealtimeSnapshotReader(
        const ScopedRealtimeSnapshotReader&) = delete;
    ScopedRealtimeSnapshotReader& operator=(
        const ScopedRealtimeSnapshotReader&) = delete;

private:
    std::atomic<std::uint32_t>& readers;
};

#if JUCE_WINDOWS
class AudioCallbackMMCSSRegistration final
{
public:
    AudioCallbackMMCSSRegistration() noexcept
    {
        handle = AvSetMmThreadCharacteristicsW(L"Pro Audio", &taskIndex);
        if (handle == nullptr)
        {
            errorCode = GetLastError();
            return;
        }

        priorityApplied =
            AvSetMmThreadPriority(handle, AVRT_PRIORITY_HIGH) != FALSE;
        if (! priorityApplied)
            errorCode = GetLastError();
    }

    ~AudioCallbackMMCSSRegistration()
    {
        if (handle != nullptr)
            AvRevertMmThreadCharacteristics(handle);
    }

    AudioCallbackMMCSSRegistration(
        const AudioCallbackMMCSSRegistration&) = delete;
    AudioCallbackMMCSSRegistration& operator=(
        const AudioCallbackMMCSSRegistration&) = delete;

    bool isActive() const noexcept
    {
        return handle != nullptr;
    }

    bool isPriorityApplied() const noexcept
    {
        return priorityApplied;
    }

    std::uint32_t getTaskIndex() const noexcept
    {
        return static_cast<std::uint32_t>(taskIndex);
    }

    std::uint32_t getErrorCode() const noexcept
    {
        return static_cast<std::uint32_t>(errorCode);
    }

private:
    HANDLE handle = nullptr;
    DWORD taskIndex = 0;
    DWORD errorCode = ERROR_SUCCESS;
    bool priorityApplied = false;
};

uint64_t fileTimeToUint64 (const FILETIME& fileTime) noexcept
{
    return (static_cast<uint64_t> (fileTime.dwHighDateTime) << 32)
        | static_cast<uint64_t> (fileTime.dwLowDateTime);
}

double getProcessCpuUsagePercent() noexcept
{
    static std::atomic<uint64_t> lastProcessTime100ns { 0 };
    static std::atomic<double> lastWallTimeMs { 0.0 };

    FILETIME creationTime {};
    FILETIME exitTime {};
    FILETIME kernelTime {};
    FILETIME userTime {};
    if (! GetProcessTimes(GetCurrentProcess(), &creationTime, &exitTime, &kernelTime, &userTime))
        return -1.0;

    const auto processTime100ns = fileTimeToUint64(kernelTime) + fileTimeToUint64(userTime);
    const auto nowMs = juce::Time::getMillisecondCounterHiRes();
    const auto previousProcessTime100ns = lastProcessTime100ns.exchange(processTime100ns, std::memory_order_acq_rel);
    const auto previousWallTimeMs = lastWallTimeMs.exchange(nowMs, std::memory_order_acq_rel);
    if (previousProcessTime100ns == 0 || previousWallTimeMs <= 0.0)
        return -1.0;

    const auto processDelta100ns = processTime100ns > previousProcessTime100ns
        ? processTime100ns - previousProcessTime100ns
        : 0;
    const auto wallDelta100ns = (nowMs - previousWallTimeMs) * 10000.0;
    if (processDelta100ns == 0 || wallDelta100ns <= 0.0)
        return 0.0;

    SYSTEM_INFO systemInfo {};
    GetSystemInfo(&systemInfo);
    const auto processorCount = systemInfo.dwNumberOfProcessors > 0 ? systemInfo.dwNumberOfProcessors : DWORD { 1 };
    const auto usage = (static_cast<double> (processDelta100ns) / (wallDelta100ns * static_cast<double> (processorCount))) * 100.0;
    return juce::jlimit(0.0, 100.0, usage);
}
#endif

