        source.ampBoost.store(0.62f);
        source.ampVoice.store(0.34f);
        source.ampMix.store(0.93f);
        source.ampOutputDb.store(-3.5f);
        source.bassDb.store(3.25f);
        source.midDb.store(-2.75f);
