static bool isOpenStudioBuiltInParameterEligible(
    juce::AudioProcessor* processor,
    const juce::String& parameterId,
    juce::DynamicObject* parameter)
{
    if (processor == nullptr || parameter == nullptr || parameterId.isEmpty())
        return false;

    if (dynamic_cast<S13NAMRack*>(processor) == nullptr)
        return false;

    static const juce::StringArray excludedNAMParameters {
        "instrumentProfile",
        "calibrationReferenceDbu",
        "pedalCalibrationMode",
        "pedalOverrideInputLevelDbu",
        "pedalOverrideOutputLevelDbu",
        "ampCalibrationMode",
        "ampOverrideInputLevelDbu",
        "ampOverrideOutputLevelDbu",
        "auditionSource"
    };
    if (excludedNAMParameters.contains(parameterId))
        return false;

    if (parameter->hasProperty("automatable")
        && ! static_cast<bool>(parameter->getProperty("automatable")))
    {
        return false;
    }

    if (parameter->getProperty("graphRole").toString() == "calibration")
        return false;

    const auto type = parameter->getProperty("type").toString();
    return type == "continuous" || type == "toggle" || type == "enum";
}

juce::var AudioEngine::getPluginParameters(const juce::String& trackId, int fxIndex, bool isInputFX)
{
    const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
    juce::Array<juce::var> paramList;

    auto it = trackMap.find(trackId);
    if (it == trackMap.end() || !it->second)
        return paramList;

    auto* track = it->second;
    juce::AudioProcessor* processor = nullptr;

    if (isInputFX)
    {
        if (fxIndex >= 0 && fxIndex < track->getNumInputFX())
            processor = track->getInputFXProcessor(fxIndex);
    }
    else
    {
        if (fxIndex >= 0 && fxIndex < track->getNumTrackFX())
            processor = track->getTrackFXProcessor(fxIndex);
    }

    if (!processor)
        return paramList;

    // Use the modern JUCE parameter API — skip internal MIDI CC parameters
    // (plugins like Amplitube expose CC 0-127 x 16 channels = 2048 internal params)
    const juce::ScopedLock processorLock(processor->getCallbackLock());
    const auto& params = processor->getParameters();
    for (int i = 0; i < params.size(); ++i)
    {
        auto* param = params[i];
        auto name = param->getName(128);

        // Filter out MIDI CC / internal mapping parameters (Reaper hides these too)
        auto nameLower = name.toLowerCase();
        if (nameLower.startsWith("midi cc") || nameLower.startsWith("cc #")
            || nameLower.contains("midi cc ") || nameLower.contains("midi ch"))
            continue;

        juce::DynamicObject::Ptr paramInfo = new juce::DynamicObject();
        paramInfo->setProperty("index", i);
        paramInfo->setProperty("name", name);
        paramInfo->setProperty("value", param->getValue());
        paramInfo->setProperty("text", param->getCurrentValueAsText());
        paramInfo->setProperty("builtIn", false);
        paramList.add(juce::var(paramInfo.get()));
    }

    if (paramList.isEmpty())
    {
        const auto schema = describeBuiltInProcessor(
            processor,
            isInputFX ? "input" : "track",
            fxIndex);
        if (auto* schemaObject = schema.getDynamicObject())
        {
            if (auto* builtInParameters = schemaObject->getProperty("parameters").getArray())
            {
                int stableIndex = 0;
                for (const auto& parameterVar : *builtInParameters)
                {
                    auto* parameter = parameterVar.getDynamicObject();
                    if (parameter == nullptr)
                        continue;

                    const auto parameterId = parameter->getProperty("id").toString();
                    if (! isOpenStudioBuiltInParameterEligible(processor, parameterId, parameter))
                        continue;

                    OpenStudioBuiltInAutomationDescriptor descriptor;
                    descriptor.minimum = static_cast<float>(static_cast<double>(parameter->getProperty("min")));
                    descriptor.maximum = static_cast<float>(static_cast<double>(parameter->getProperty("max")));
                    descriptor.currentValue = static_cast<float>(static_cast<double>(parameter->getProperty("value")));
                    const auto parameterType = parameter->getProperty("type").toString();
                    descriptor.discrete = parameterType == "toggle" || parameterType == "enum";
                    descriptor.curve =
                        getOpenStudioBuiltInParameterCurve(
                            processor, parameterId);
                    if (! std::isfinite(descriptor.minimum)
                        || ! std::isfinite(descriptor.maximum)
                        || descriptor.maximum <= descriptor.minimum)
                    {
                        continue;
                    }

                    const auto normalized =
                        openStudioBuiltInValueToNormalized(
                            descriptor, descriptor.currentValue);
                    const auto type = parameterType;
                    const auto unit = parameter->getProperty("unit").toString();
                    juce::String valueText;
                    if (type == "toggle")
                    {
                        valueText = descriptor.currentValue >= 0.5f ? "On" : "Off";
                    }
                    else if (type == "enum")
                    {
                        if (auto* options = parameter->getProperty("enumOptions").getArray())
                        {
                            const int optionIndex = juce::jlimit(0, juce::jmax(0, options->size() - 1),
                                static_cast<int>(std::round(descriptor.currentValue)));
                            if (options->size() > 0)
                                if (auto* option = options->getReference(optionIndex).getDynamicObject())
                                    valueText = option->getProperty("label").toString();
                        }
                    }
                    if (valueText.isEmpty() && parameterId == "eqHPFHz")
                    {
                        valueText = descriptor.currentValue
                                < openStudioGraphicEqHighPassMinimumHz
                            ? "OFF"
                            : juce::String(juce::roundToInt(
                                  descriptor.currentValue))
                                + " Hz";
                    }
                    if (valueText.isEmpty() && parameterId == "preEqHPFHz")
                    {
                        valueText = descriptor.currentValue
                                < openStudioPreEqHighPassMinimumHz
                            ? "OFF"
                            : juce::String(juce::roundToInt(
                                  descriptor.currentValue))
                                + " Hz";
                    }
                    if (valueText.isEmpty() && parameterId == "preEqLPFHz")
                    {
                        valueText = descriptor.currentValue
                                >= openStudioPreEqLowPassOffBoundaryHz
                            ? "OFF"
                            : juce::String(
                                  descriptor.currentValue / 1000.0f, 1)
                                + " kHz";
                    }
                    if (valueText.isEmpty() && parameterId == "eqLPFHz")
                    {
                        valueText = descriptor.currentValue
                                >= openStudioGraphicEqLowPassOffBoundaryHz
                            ? "OFF"
                            : juce::String(
                                  descriptor.currentValue / 1000.0f, 1)
                                + " kHz";
                    }
                    if (valueText.isEmpty())
                    {
                        valueText = juce::String(descriptor.currentValue,
                            std::abs(descriptor.currentValue) >= 100.0f ? 0 : 2);
                        if (unit.isNotEmpty())
                            valueText << " " << unit;
                    }

                    juce::DynamicObject::Ptr paramInfo = new juce::DynamicObject();
                    paramInfo->setProperty("index", stableIndex++);
                    paramInfo->setProperty("paramId", parameterId);
                    paramInfo->setProperty("name", parameter->getProperty("label"));
                    paramInfo->setProperty("value", normalized);
                    paramInfo->setProperty("text", valueText);
                    paramInfo->setProperty("builtIn", true);
                    paramInfo->setProperty("min", descriptor.minimum);
                    paramInfo->setProperty("max", descriptor.maximum);
                    paramInfo->setProperty("discrete", descriptor.discrete);
                    paramInfo->setProperty("type", type);
                    paramInfo->setProperty("unit", unit);
                    paramInfo->setProperty("enumOptions", parameter->getProperty("enumOptions"));
                    paramList.add(juce::var(paramInfo.get()));
                }
            }
        }
    }

    return paramList;
}

juce::var AudioEngine::getBuiltInPluginSchema(const juce::String& trackId, const juce::String& chainType, int fxIndex)
{
    if (chainType == "instrument")
    {
        const juce::ScopedTryLock sl(mainProcessorGraph->getCallbackLock());
        if (! sl.isLocked())
            return describeFallbackInstrument(nullptr, chainType, fxIndex);

        auto it = trackMap.find(trackId);
        return describeFallbackInstrument(it != trackMap.end() ? it->second : nullptr, chainType, fxIndex);
    }

    // Built-in effects publish ordinary editor controls atomically. Resolve
    // them from immutable realtime snapshots so opening or refreshing an
    // editor never owns either callback lock while its schema is assembled.
    // S13EQ's analyzer is also a lock-free audio-to-UI publication.
    const auto publishedOwner =
        getPublishedBuiltInProcessor(trackId, chainType, fxIndex);
    if (supportsLockFreeBuiltInControlPublication(
            publishedOwner.processor.get()))
    {
        return describeBuiltInProcessor(
            publishedOwner.processor.get(), chainType, fxIndex);
    }

    if (chainType == "master")
    {
        int slotId = 0;
        {
            const juce::ScopedTryLock sl(mainProcessorGraph->getCallbackLock());
            if (! sl.isLocked())
                return describeBuiltInProcessor(nullptr, chainType, fxIndex);

            if (const auto* slot = findDesiredStageSlot(desiredMasterStageSpec, fxIndex))
                slotId = slot->slotId;
        }

        auto activeStage = std::atomic_load_explicit(&realtimeMasterFXSnapshot, std::memory_order_acquire);
        if (const auto* activeSlot = findActiveStageSlot(activeStage, slotId))
        {
            auto* processor = activeSlot->processor.get();
            const juce::ScopedTryLock processorLock(processor->getCallbackLock());
            if (processorLock.isLocked())
                return describeBuiltInProcessor(processor, chainType, fxIndex);
        }

        return describeBuiltInProcessor(nullptr, chainType, fxIndex);
    }

    const juce::ScopedTryLock sl(mainProcessorGraph->getCallbackLock());
    if (! sl.isLocked())
        return describeBuiltInProcessor(nullptr, chainType, fxIndex);

    auto it = trackMap.find(trackId);
    if (it == trackMap.end() || !it->second)
        return describeBuiltInProcessor(nullptr, chainType, fxIndex);

    auto* processor = chainType == "input"
        ? it->second->getInputFXProcessor(fxIndex)
        : it->second->getTrackFXProcessor(fxIndex);
    if (processor == nullptr)
        return describeBuiltInProcessor(nullptr, chainType, fxIndex);

    const juce::ScopedTryLock processorLock(processor->getCallbackLock());
    return processorLock.isLocked()
        ? describeBuiltInProcessor(processor, chainType, fxIndex)
        : describeBuiltInProcessor(nullptr, chainType, fxIndex);
}

juce::var AudioEngine::getNAMRackDiagnostics(
    const juce::String& trackId,
    const juce::String& chainType,
    int fxIndex)
{
    const auto processorOwner =
        getPublishedBuiltInProcessor(
            trackId, chainType, fxIndex);

    // This endpoint deliberately avoids both processor callback locks. The
    // diagnostic snapshot may briefly serialize non-realtime model metadata,
    // but that lock is never acquired by the audio callback; live UI telemetry
    // therefore cannot make the audio thread skip a NAM block.
    if (auto* rack = dynamic_cast<S13NAMRack*>(
            processorOwner.processor.get()))
        return rack->getDiagnosticState();

    return {};
}

juce::var AudioEngine::getBuiltInPluginState(const juce::String& trackId, const juce::String& chainType, int fxIndex)
{
    const auto schema = getBuiltInPluginSchema(trackId, chainType, fxIndex);
    auto* root = new juce::DynamicObject();
    root->setProperty("schemaVersion", 1);
    root->setProperty("chain", chainType);
    root->setProperty("fxIndex", fxIndex);

    juce::DynamicObject* schemaObject = schema.getDynamicObject();
    if (schemaObject != nullptr)
    {
        root->setProperty("name", schemaObject->getProperty("name"));
        juce::DynamicObject::Ptr values = new juce::DynamicObject();
        const auto paramsVar = schemaObject->getProperty("parameters");
        if (auto* params = paramsVar.getArray())
        {
            for (const auto& paramVar : *params)
            {
                if (auto* param = paramVar.getDynamicObject())
                    values->setProperty(param->getProperty("id").toString(), param->getProperty("value"));
            }
        }
        root->setProperty("values", values.get());
        const auto modelState = schemaObject->getProperty("modelState");
        if (!modelState.isVoid())
            root->setProperty("modelState", modelState);
        const auto visualization = schemaObject->getProperty("visualization");
        if (!visualization.isVoid())
            root->setProperty("visualization", visualization);
        const auto uiState = schemaObject->getProperty("uiState");
        if (!uiState.isVoid())
            root->setProperty("uiState", uiState);
    }

    // Internal serialization identities stay outside public/automatable
    // values. The unreleased rack exposes only its current engines.
    const auto processorOwner =
        getPublishedBuiltInProcessor(
            trackId, chainType, fxIndex);
    if (const auto* rack =
            dynamic_cast<const S13NAMRack*>(
                processorOwner.processor.get()))
    {
        if (auto* values = root->getProperty(
                "values").getDynamicObject())
        {
            const float preHpfHz = rack->preEqHPFHz.load(
                std::memory_order_relaxed);
            const float preLpfHz = rack->preEqLPFHz.load(
                std::memory_order_relaxed);
            const float rememberedPreHPFHz =
                rack->preEqHPFLastActiveHz.load(
                    std::memory_order_relaxed);
            const float rememberedPreLPFHz =
                rack->preEqLPFLastActiveHz.load(
                    std::memory_order_relaxed);
            values->setProperty(
                "preEqHPFLastActiveHz",
                std::isfinite(preHpfHz) && preHpfHz >= 35.0f
                    ? juce::jlimit(35.0f, 180.0f, preHpfHz)
                    : (std::isfinite(rememberedPreHPFHz)
                        ? juce::jlimit(35.0f, 180.0f, rememberedPreHPFHz)
                        : 80.0f));
            values->setProperty(
                "preEqLPFLastActiveHz",
                std::isfinite(preLpfHz) && preLpfHz < 22000.0f
                    ? juce::jlimit(3000.0f, 20000.0f, preLpfHz)
                    : (std::isfinite(rememberedPreLPFHz)
                        ? juce::jlimit(3000.0f, 20000.0f, rememberedPreLPFHz)
                        : 12000.0f));
            const float hpfHz = rack->eqHPFHz.load(
                std::memory_order_relaxed);
            const float lpfHz = rack->eqLPFHz.load(
                std::memory_order_relaxed);
            const float rememberedHPFHz =
                rack->eqHPFLastActiveHz.load(
                    std::memory_order_relaxed);
            const float rememberedLPFHz =
                rack->eqLPFLastActiveHz.load(
                    std::memory_order_relaxed);
            values->setProperty(
                "eqHPFLastActiveHz",
                std::isfinite(hpfHz) && hpfHz >= 20.0f
                    ? juce::jlimit(20.0f, 500.0f, hpfHz)
                    : (std::isfinite(rememberedHPFHz)
                        ? juce::jlimit(
                            20.0f, 500.0f, rememberedHPFHz)
                        : 80.0f));
            values->setProperty(
                "eqLPFLastActiveHz",
                std::isfinite(lpfHz) && lpfHz < 22000.0f
                    ? juce::jlimit(3000.0f, 20000.0f, lpfHz)
                    : (std::isfinite(rememberedLPFHz)
                        ? juce::jlimit(
                            3000.0f, 20000.0f, rememberedLPFHz)
                        : 12000.0f));
        }
        auto* dspState =
            new juce::DynamicObject();
        dspState->setProperty(
            "namEffectsDspVersion",
            S13NAMRack::currentNAMEffectsDspVersion);
        dspState->setProperty(
            "reverbEngineVersion",
            S13NAMRack::currentReverbEngineVersion);
        root->setProperty(
            "dspState",
            juce::var(dspState));
    }

    return juce::var(root);
}

bool AudioEngine::setBuiltInPluginParam(const juce::String& trackId, const juce::String& chainType, int fxIndex,
                                        const juce::String& paramId, float value)
{
    if (chainType == "instrument")
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        auto it = trackMap.find(trackId);
        return it != trackMap.end() && it->second != nullptr
            ? it->second->setFallbackInstrumentParam(paramId, value)
            : false;
    }

    if (chainType == "input" || chainType == "track")
    {
        const auto publishedOwner =
            getPublishedBuiltInProcessor(
                trackId, chainType, fxIndex);
        auto* publishedProcessor =
            publishedOwner.processor.get();
        if (supportsLockFreeBuiltInControlPublication(
                publishedProcessor)
            && ! requiresLockedBuiltInControlMutation(
                publishedProcessor, paramId))
        {
            const bool applied =
                setBuiltInProcessorParam(
                    publishedProcessor, paramId, value);
            if (applied && publishedOwner.track != nullptr)
                publishedOwner.track
                    ->invalidatePluginAutomationCache();
            if (applied && paramId == "auditionSource")
            {
                if (auto* rack =
                        dynamic_cast<S13NAMRack*>(
                            publishedProcessor))
                {
                    juce::Logger::writeToLog(
                        "AudioEngine: NAM auditionSource="
                        + juce::String(value)
                        + " track=" + trackId
                        + " chain=" + chainType
                        + " fx=" + juce::String(fxIndex)
                        + " diagnostics="
                        + juce::JSON::toString(
                            rack->getDiagnosticState(), false));
                }
            }
            return applied;
        }
    }

    if (chainType == "master")
    {
        int slotId = 0;
        {
            const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
            if (const auto* slot = findDesiredStageSlot(desiredMasterStageSpec, fxIndex))
                slotId = slot->slotId;
        }

        if (slotId == 0)
            return false;

        juce::String serializedState;
        bool latencyChanged = false;
        auto activeStage = std::atomic_load_explicit(&realtimeMasterFXSnapshot, std::memory_order_acquire);
        if (const auto* activeSlot = findActiveStageSlot(activeStage, slotId))
        {
            if (!activeSlot->processor)
                return false;

            auto* processor = activeSlot->processor.get();
            const bool lockFreeScalarMutation =
                supportsLockFreeBuiltInControlPublication(
                    processor)
                && ! requiresLockedBuiltInControlMutation(
                    processor, paramId);
            if (lockFreeScalarMutation)
            {
                if (! setBuiltInProcessorParam(
                        processor, paramId, value))
                    return false;
                serializedState =
                    serialiseProcessorStateToBase64(
                        processor);
            }
            else
            {
                const juce::ScopedLock processorLock(
                    processor->getCallbackLock());
                const int latencyBefore =
                    processor->getLatencySamples();
                if (! setBuiltInProcessorParam(
                        processor, paramId, value))
                    return false;
                latencyChanged =
                    processor->getLatencySamples()
                    != latencyBefore;
                serializedState =
                    serialiseProcessorStateToBase64(
                        processor);
            }
            if (activeSlot->bypassDelay != nullptr)
            {
                activeSlot->bypassDelay
                    ->publishedLatency.store(
                        juce::jmax(
                            0,
                            processor
                                ->getLatencySamples()),
                        std::memory_order_release);
            }
        }
        else
        {
            return false;
        }

        {
            const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
            if (auto* slot = findDesiredStageSlot(desiredMasterStageSpec, fxIndex))
                slot->serializedState = serializedState;
        }
        if (latencyChanged)
            recalculatePDC();
        return true;
    }

    {
        bool applied = false;
        bool latencyChanged = false;
        {
            const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
            auto it = trackMap.find(trackId);
            if (it == trackMap.end() || !it->second)
                return false;

            auto* processor = chainType == "input"
                ? it->second->getInputFXProcessor(fxIndex)
                : it->second->getTrackFXProcessor(fxIndex);
            if (processor == nullptr)
                return false;

            const bool lockFreeScalarMutation =
                supportsLockFreeBuiltInControlPublication(
                    processor)
                && ! requiresLockedBuiltInControlMutation(
                    processor, paramId);
            if (lockFreeScalarMutation)
            {
                // Ordinary built-in controls are atomic scalar publications.
                // Do not take the processor callback lock for UI traffic:
                // TrackProcessor deliberately skips an effect block when that
                // lock is busy, which would turn a knob drag into audible
                // discontinuities.
                applied = setBuiltInProcessorParam(processor, paramId, value);
            }
            else
            {
                const juce::ScopedLock processorLock(processor->getCallbackLock());
                const int latencyBefore = processor->getLatencySamples();
                applied = setBuiltInProcessorParam(processor, paramId, value);
                latencyChanged = applied && processor->getLatencySamples() != latencyBefore;
            }
            if (applied)
                it->second->invalidatePluginAutomationCache();
            if (applied && paramId == "auditionSource")
            {
                if (auto* rack = dynamic_cast<S13NAMRack*>(processor))
                {
                    juce::Logger::writeToLog("AudioEngine: NAM auditionSource="
                        + juce::String(value)
                        + " track=" + trackId
                        + " chain=" + chainType
                        + " fx=" + juce::String(fxIndex)
                        + " diagnostics=" + juce::JSON::toString(rack->getDiagnosticState(), false));
                }
            }
        }

        if (latencyChanged)
            recalculatePDC();

        return applied;
    }
}

bool AudioEngine::setBuiltInPluginState(const juce::String& trackId, const juce::String& chainType, int fxIndex,
                                        const juce::String& stateJSON,
                                        const std::function<std::shared_ptr<void>()>& publicationLeaseFactory)
{
    const auto parsed = juce::JSON::parse(stateJSON);
    if (parsed.isVoid())
        return false;

    auto* stateObject = parsed.getDynamicObject();
    if (stateObject == nullptr)
        return false;

    juce::DynamicObject* modelObject = nullptr;
    if (auto* nested = stateObject->getProperty("modelState").getDynamicObject())
        modelObject = nested;
    else
        modelObject = stateObject;

    const bool clearPedal = modelObject->hasProperty("clearPedalModel")
        && static_cast<bool>(modelObject->getProperty("clearPedalModel"));
    const bool clearAmp = modelObject->hasProperty("clearAmpModel")
        && static_cast<bool>(modelObject->getProperty("clearAmpModel"));
    const bool clearCab = modelObject->hasProperty("clearCabIR")
        && static_cast<bool>(modelObject->getProperty("clearCabIR"));
    const bool pedalPathSpecified = clearPedal || modelObject->hasProperty("pedalModelPath");
    const bool ampPathSpecified = clearAmp || modelObject->hasProperty("ampModelPath");
    const bool cabPathSpecified = clearCab || modelObject->hasProperty("cabIRPath");
    bool legacyModelSizeSpecified = false;
    float legacyModelSize = 1.0f;
    if (auto* values =
            stateObject->getProperty(
                "values").getDynamicObject();
        values != nullptr
        && values->hasProperty("namModelSize"))
    {
        legacyModelSizeSpecified = true;
        legacyModelSize = juce::jlimit(
            0.0f,
            1.0f,
            static_cast<float>(
                static_cast<double>(
                    values->getProperty(
                        "namModelSize"))));
    }
    if (auto* parameters =
            stateObject->getProperty(
                "parameters").getArray())
    {
        for (const auto& parameterValue :
             *parameters)
        {
            if (auto* parameter =
                    parameterValue.getDynamicObject();
                parameter != nullptr
                && parameter->getProperty(
                       "id").toString()
                    == "namModelSize")
            {
                legacyModelSizeSpecified = true;
                legacyModelSize = juce::jlimit(
                    0.0f,
                    1.0f,
                    static_cast<float>(
                        static_cast<double>(
                            parameter->getProperty(
                                "value"))));
            }
        }
    }
    const bool pedalModelSizeSpecified =
        modelObject->hasProperty(
            "pedalModelSize")
        || legacyModelSizeSpecified;
    const bool ampModelSizeSpecified =
        modelObject->hasProperty(
            "ampModelSize")
        || legacyModelSizeSpecified;
    const float requestedPedalModelSize =
        juce::jlimit(
            0.0f,
            1.0f,
            static_cast<float>(
                static_cast<double>(
                    modelObject->hasProperty(
                        "pedalModelSize")
                        ? modelObject->getProperty(
                              "pedalModelSize")
                        : juce::var(
                              legacyModelSize))));
    const float requestedAmpModelSize =
        juce::jlimit(
            0.0f,
            1.0f,
            static_cast<float>(
                static_cast<double>(
                    modelObject->hasProperty(
                        "ampModelSize")
                        ? modelObject->getProperty(
                              "ampModelSize")
                        : juce::var(
                              legacyModelSize))));
    const bool resourcesRequested =
        pedalPathSpecified
        || ampPathSpecified
        || cabPathSpecified
        || pedalModelSizeSpecified
        || ampModelSizeSpecified;
    const auto pedalPath = clearPedal ? juce::String() : modelObject->getProperty("pedalModelPath").toString();
    const auto ampPath = clearAmp ? juce::String() : modelObject->getProperty("ampModelPath").toString();
    const auto cabPath = clearCab ? juce::String() : modelObject->getProperty("cabIRPath").toString();
    const bool cabRequestedEnabledSpecified = modelObject->hasProperty("cabRequestedEnabled");
    const bool requestedCabEnabled = cabRequestedEnabledSpecified
        && static_cast<bool>(modelObject->getProperty("cabRequestedEnabled"));
    const bool pedalDeclaredCaptureTypeSpecified =
        modelObject->hasProperty("pedalDeclaredCaptureType")
        || modelObject->hasProperty("pedalCaptureType");
    const bool ampDeclaredCaptureTypeSpecified =
        modelObject->hasProperty("ampDeclaredCaptureType")
        || modelObject->hasProperty("ampCaptureType");
    const auto pedalDeclaredCaptureType =
        modelObject->hasProperty("pedalDeclaredCaptureType")
        ? modelObject->getProperty("pedalDeclaredCaptureType").toString()
        : modelObject->getProperty("pedalCaptureType").toString();
    const auto ampDeclaredCaptureType =
        modelObject->hasProperty("ampDeclaredCaptureType")
        ? modelObject->getProperty("ampDeclaredCaptureType").toString()
        : modelObject->getProperty("ampCaptureType").toString();
    const bool portableNAMToneState = stateObject->getProperty("modelState").isObject();
    const bool explicitDirectLoadPolicy = stateObject->hasProperty("applyDirectLoadPolicy")
        && static_cast<bool>(stateObject->getProperty("applyDirectLoadPolicy"));
    bool dspStateRequested = false;
    bool invalidDspStateRequested = false;
    bool invalidEffectsVersionRequested = false;
    bool effectsVersionPropertyPresent = false;
    int storedEffectsVersion = 0;
    if (auto* dspState =
            stateObject->getProperty(
                "dspState").getDynamicObject();
        dspState != nullptr)
    {
        dspStateRequested = dspState->getProperties().size() > 0;
        if (dspState->hasProperty(
                "namEffectsDspVersion"))
        {
            effectsVersionPropertyPresent = true;
            const double rawEffectsVersion =
                static_cast<double>(
                    dspState->getProperty(
                        "namEffectsDspVersion"));
            if (std::isfinite(rawEffectsVersion)
                && rawEffectsVersion
                       == std::floor(rawEffectsVersion)
                && rawEffectsVersion >= 1.0
                && (rawEffectsVersion
                        <= static_cast<double>(
                            S13NAMRack::currentNAMEffectsDspVersion)
                    || rawEffectsVersion
                        == static_cast<double>(
                            S13NAMRack::developmentNAMEffectsDspVersionAlias)))
            {
                storedEffectsVersion = rawEffectsVersion
                        == static_cast<double>(
                            S13NAMRack::developmentNAMEffectsDspVersionAlias)
                    ? S13NAMRack::developmentNAMEffectsDspVersionAliasSourceVersion
                    : juce::roundToInt(rawEffectsVersion);
            }
            else
            {
                invalidEffectsVersionRequested = true;
            }
        }
        if (dspState->hasProperty("reverbEngineVersion"))
        {
            const double rawReverbVersion = static_cast<double>(
                dspState->getProperty("reverbEngineVersion"));
            if (! std::isfinite(rawReverbVersion)
                || std::abs(
                       rawReverbVersion
                       - std::round(rawReverbVersion)) > 1.0e-6
                || rawReverbVersion < 1.0
                || rawReverbVersion
                       > static_cast<double>(
                           S13NAMRack::currentReverbEngineVersion))
            {
                invalidDspStateRequested = true;
            }
        }
    }
    const bool completePortableNAMBundle =
        portableNAMToneState
        && stateObject->hasProperty("schemaVersion")
        && (stateObject->getProperty("values").isObject()
            || stateObject->getProperty("parameters").isArray());
    if (invalidDspStateRequested
        || (invalidEffectsVersionRequested
            && ! completePortableNAMBundle))
        return false;
    // V11 changes only route ownership. V10 already contains the current
    // component/Delay state contracts, so do not run older component-default
    // migrations over a complete V10 bundle while dropping retired inputMode.
    const bool preV10PortableBundle = completePortableNAMBundle
        && (! effectsVersionPropertyPresent
            || storedEffectsVersion
                   < S13NAMRack::delayV10IntroducedNAMEffectsDspVersion);

    std::vector<std::pair<juce::String, float>> parameterValues;
    const auto appendParameter = [&] (const juce::String& id, const juce::var& rawValue)
    {
        if (id.isEmpty()
            || id == "namModelSize"
            || (portableNAMToneState
                && id == "calibrationReferenceDbu"))
            return;
        parameterValues.emplace_back(id, static_cast<float>(static_cast<double>(rawValue)));
    };

    if (auto* valuesObject = stateObject->getProperty("values").getDynamicObject())
    {
        const auto& properties = valuesObject->getProperties();
        for (int index = 0; index < properties.size(); ++index)
            appendParameter(properties.getName(index).toString(), properties.getValueAt(index));
    }

    if (auto* parameters = stateObject->getProperty("parameters").getArray())
    {
        for (const auto& paramVar : *parameters)
        {
            if (auto* param = paramVar.getDynamicObject())
            {
                appendParameter(param->getProperty("id").toString(), param->getProperty("value"));
            }
        }
    }

    if (completePortableNAMBundle)
    {
        const auto findParameter = [&] (const juce::String& id)
        {
            return std::find_if(
                parameterValues.begin(),
                parameterValues.end(),
                [&] (const auto& entry)
                {
                    return entry.first == id;
                });
        };
        const auto parameterOrDefault = [&] (
            const juce::String& id,
            float fallback)
        {
            const auto found = findParameter(id);
            return found != parameterValues.end()
                ? found->second
                : fallback;
        };
        const bool legacyDistortionMode =
            parameterOrDefault("precisionDriveMode", 0.0f) >= 0.5f;
        const bool hasDedicatedDistortionState =
            findParameter("chaosMode") != parameterValues.end()
            || findParameter("chaosDrive") != parameterValues.end()
            || findParameter("chaosTone") != parameterValues.end()
            || findParameter("chaosLevelDb") != parameterValues.end();
        const float originalPrecisionVolume =
            parameterOrDefault(
                "precisionDriveVolumeDb",
                preV10PortableBundle ? 0.0f : 9.0f);
        const float legacyCompressorDetail = juce::jlimit(
            0.0f,
            1.0f,
            parameterOrDefault("compressorDetail", 0.55f));
        const bool hasCompressorAttack =
            findParameter("compressorAttackMs")
                != parameterValues.end();
        const bool hasCompressorRelease =
            findParameter("compressorReleaseMs")
                != parameterValues.end();
        const bool hasCabRoomEnabled =
            findParameter("cabRoomEnabled")
                != parameterValues.end();
        const bool hasCabDoublerEnabled =
            findParameter("cabDoublerEnabled")
                != parameterValues.end();
        const float legacyCabRoomAmount =
            parameterOrDefault("cabRoomAmount", 0.0f);
        const float legacyCabDoublerMix =
            parameterOrDefault("cabDoublerMix", 0.0f);
        const bool hasCurrentGraphicEqFilters =
            storedEffectsVersion
                    >= S13NAMRack::graphicEqFiltersIntroducedNAMEffectsDspVersion
            && storedEffectsVersion
                    <= S13NAMRack::currentNAMEffectsDspVersion;
        const bool hasCurrentPreEq =
            storedEffectsVersion
                    >= S13NAMRack::preEqIntroducedNAMEffectsDspVersion
            && storedEffectsVersion
                    <= S13NAMRack::currentNAMEffectsDspVersion;
        const bool hasEightBandPreEq =
            storedEffectsVersion
                    >= S13NAMRack::eightBandPreEqIntroducedNAMEffectsDspVersion
            && storedEffectsVersion
                    <= S13NAMRack::currentNAMEffectsDspVersion;
        const float requestedPreEqHPFHz =
            parameterOrDefault("preEqHPFHz", 0.0f);
        const float requestedPreEqLPFHz =
            parameterOrDefault("preEqLPFHz", 24000.0f);
        const float requestedPreEqHPFLastActiveHz =
            parameterOrDefault("preEqHPFLastActiveHz", 80.0f);
        const float requestedPreEqLPFLastActiveHz =
            parameterOrDefault("preEqLPFLastActiveHz", 12000.0f);
        const float requestedEqHPFHz =
            parameterOrDefault("eqHPFHz", 0.0f);
        const float requestedEqLPFHz =
            parameterOrDefault("eqLPFHz", 24000.0f);
        const float requestedEqHPFLastActiveHz =
            parameterOrDefault("eqHPFLastActiveHz", 80.0f);
        const float requestedEqLPFLastActiveHz =
            parameterOrDefault("eqLPFLastActiveHz", 12000.0f);

        const auto setOrAppendParameter = [&] (
            const juce::String& id,
            float value)
        {
            const auto found = findParameter(id);
            if (found != parameterValues.end())
                found->second = value;
            else
                parameterValues.emplace_back(id, value);
        };
        const auto appendDefault = [&] (
            const juce::String& id,
            float value)
        {
            if (findParameter(id) == parameterValues.end())
                parameterValues.emplace_back(id, value);
        };

        parameterValues.erase(
            std::remove_if(
                parameterValues.begin(),
                parameterValues.end(),
                [] (const auto& parameter)
                {
                    return parameter.first == "inputMode"
                        || parameter.first == "precisionDriveVoice";
                }),
            parameterValues.end());
        appendDefault("compressorEnabled", 0.0f);
        appendDefault("compressorAttackMs", 21.9f);
        appendDefault("compressorReleaseMs", 149.1f);
        appendDefault("compressorToneDb", 0.0f);
        appendDefault("compressorIntensity", 0.0f);
        appendDefault("compressorSidechainHPF", 1.0f);
        appendDefault("compressorMix", 0.65f);
        appendDefault("compressorVolumeDb", 0.0f);
        appendDefault("compressorComp", 0.35f);
        setOrAppendParameter(
            "preEqEnabled",
            hasCurrentPreEq
                    && std::isfinite(parameterOrDefault("preEqEnabled", 0.0f))
                    && parameterOrDefault("preEqEnabled", 0.0f) >= 0.5f
                ? 1.0f
                : 0.0f);
        static constexpr std::array<const char*, 8> currentPreEqBandIds {{
            "preEq120Db", "preEq250Db", "preEq500Db", "preEq1kDb",
            "preEq2k5Db", "preEq5kDb", "preEq8kDb", "preEq12kDb"
        }};
        static constexpr std::array<const char*, 7> legacyPreEqBandIds {{
            "preEq100Db", "preEq200Db", "preEq400Db", "preEq800Db",
            "preEq1k6Db", "preEq3k2Db", "preEq6k4Db"
        }};
        for (size_t index = 0; index < currentPreEqBandIds.size(); ++index)
        {
            const char* const id = currentPreEqBandIds[index];
            const char* const sourceId = hasEightBandPreEq
                ? id
                : (index < legacyPreEqBandIds.size()
                    ? legacyPreEqBandIds[index]
                    : nullptr);
            const float requested = sourceId != nullptr
                ? parameterOrDefault(sourceId, 0.0f)
                : 0.0f;
            setOrAppendParameter(
                id,
                hasCurrentPreEq && std::isfinite(requested)
                    ? juce::jlimit(-12.0f, 12.0f, requested)
                    : 0.0f);
        }
        const float canonicalPreEqHPFHz = hasCurrentPreEq
            ? (! std::isfinite(requestedPreEqHPFHz)
                    || requestedPreEqHPFHz < 35.0f
                ? 0.0f
                : juce::jlimit(35.0f, 180.0f, requestedPreEqHPFHz))
            : 0.0f;
        const float canonicalPreEqLPFHz = hasCurrentPreEq
            ? (! std::isfinite(requestedPreEqLPFHz)
                    || requestedPreEqLPFHz >= 22000.0f
                ? 24000.0f
                : juce::jlimit(3000.0f, 20000.0f, requestedPreEqLPFHz))
            : 24000.0f;
        setOrAppendParameter("preEqHPFHz", canonicalPreEqHPFHz);
        setOrAppendParameter("preEqLPFHz", canonicalPreEqLPFHz);
        setOrAppendParameter(
            "preEqHPFLastActiveHz",
            ! hasCurrentPreEq
                ? 80.0f
                : (canonicalPreEqHPFHz >= 35.0f
                    ? canonicalPreEqHPFHz
                    : (std::isfinite(requestedPreEqHPFLastActiveHz)
                        ? juce::jlimit(
                            35.0f, 180.0f, requestedPreEqHPFLastActiveHz)
                        : 80.0f)));
        setOrAppendParameter(
            "preEqLPFLastActiveHz",
            ! hasCurrentPreEq
                ? 12000.0f
                : (canonicalPreEqLPFHz < 22000.0f
                    ? canonicalPreEqLPFHz
                    : (std::isfinite(requestedPreEqLPFLastActiveHz)
                        ? juce::jlimit(
                            3000.0f, 20000.0f,
                            requestedPreEqLPFLastActiveHz)
                        : 12000.0f)));
        appendDefault("precisionDriveEnabled", 0.0f);
        appendDefault("precisionDriveVolumeDb", 9.0f);
        appendDefault("precisionDriveBright", 0.55f);
        appendDefault("precisionDriveAttack", 0.50f);
        appendDefault("precisionDriveGate", 0.0f);
        appendDefault("precisionDriveDrive", 0.35f);
        appendDefault("chaosEnabled", 0.0f);
        appendDefault("chaosMode", 0.0f);
        appendDefault("chaosWeight", 0.50f);
        appendDefault("chaosDrive", 0.62f);
        appendDefault("chaosTone", 0.55f);
        appendDefault("chaosGate", 0.22f);
        appendDefault("chaosMix", 1.0f);
        appendDefault("chaosLevelDb", 0.0f);
        appendDefault(
            "cabRoomEnabled",
            ! hasCabRoomEnabled
                && std::isfinite(legacyCabRoomAmount)
                && legacyCabRoomAmount > 1.0e-4f
                ? 1.0f
                : 0.0f);
        appendDefault("cabRoomAmount", 0.22f);
        appendDefault("cabRoomWidth", 0.65f);
        appendDefault(
            "cabDoublerEnabled",
            ! hasCabDoublerEnabled
                && std::isfinite(legacyCabDoublerMix)
                && legacyCabDoublerMix > 1.0e-4f
                ? 1.0f
                : 0.0f);
        appendDefault("cabDoublerMix", 0.12f);
        appendDefault("cabDoublerDelayMs", 4.5f);
        appendDefault("cabDoublerSpread", 0.65f);
        const float canonicalEqHPFHz = hasCurrentGraphicEqFilters
            ? (! std::isfinite(requestedEqHPFHz)
                    || requestedEqHPFHz < 20.0f
                ? 0.0f
                : juce::jlimit(
                    20.0f, 500.0f, requestedEqHPFHz))
            : 0.0f;
        const float canonicalEqLPFHz = hasCurrentGraphicEqFilters
            ? (! std::isfinite(requestedEqLPFHz)
                    || requestedEqLPFHz >= 22000.0f
                ? 24000.0f
                : juce::jlimit(
                    3000.0f, 20000.0f, requestedEqLPFHz))
            : 24000.0f;
        setOrAppendParameter(
            "eqHPFHz",
            canonicalEqHPFHz);
        setOrAppendParameter(
            "eqLPFHz",
            canonicalEqLPFHz);
        setOrAppendParameter(
            "eqHPFLastActiveHz",
            ! hasCurrentGraphicEqFilters
                ? 80.0f
                : (canonicalEqHPFHz >= 20.0f
                    ? canonicalEqHPFHz
                    : (std::isfinite(requestedEqHPFLastActiveHz)
                        ? juce::jlimit(
                            20.0f,
                            500.0f,
                            requestedEqHPFLastActiveHz)
                        : 80.0f)));
        setOrAppendParameter(
            "eqLPFLastActiveHz",
            ! hasCurrentGraphicEqFilters
                ? 12000.0f
                : (canonicalEqLPFHz < 22000.0f
                    ? canonicalEqLPFHz
                    : (std::isfinite(requestedEqLPFLastActiveHz)
                        ? juce::jlimit(
                            3000.0f,
                            20000.0f,
                            requestedEqLPFLastActiveHz)
                        : 12000.0f)));
        appendDefault("eqLevelDb", 0.0f);
        appendDefault("delayMix", 0.22f);
        appendDefault("delayTimeMs", 360.0f);
        appendDefault("delayFeedback", 0.22f);
        appendDefault("delayMod", 0.18f);
        appendDefault("delayDucker", 0.12f);
        appendDefault("delayMode", 1.0f);
        appendDefault("delayPingPong", 1.0f);
        appendDefault("delayTempoSync", 0.0f);
        appendDefault("delayEnabled", 0.0f);

        const float requestedDelayMode = parameterOrDefault(
            "delayMode", 1.0f);
        float canonicalDelayMode = 1.0f;
        if (storedEffectsVersion
                >= S13NAMRack::delayV10IntroducedNAMEffectsDspVersion
            && storedEffectsVersion
                <= S13NAMRack::currentNAMEffectsDspVersion)
        {
            canonicalDelayMode = std::floor(
                juce::jlimit(
                    0.0f,
                    static_cast<float>(S13NAMRack::dualDelayMode),
                    std::isfinite(requestedDelayMode)
                        ? requestedDelayMode
                        : 1.0f)
                + 0.5f);
        }
        else if (storedEffectsVersion >= 1
                 && storedEffectsVersion
                        < S13NAMRack::currentNAMEffectsDspVersion)
        {
            canonicalDelayMode = std::floor(
                juce::jlimit(
                    0.0f,
                    static_cast<float>(S13NAMRack::analogDelayMode),
                    std::isfinite(requestedDelayMode)
                        ? requestedDelayMode
                        : 1.0f)
                + 0.5f);
        }
        bool canonicalizedDelayMode = false;
        for (auto& parameter : parameterValues)
        {
            if (parameter.first == "delayMode")
            {
                parameter.second = canonicalDelayMode;
                canonicalizedDelayMode = true;
            }
        }
        if (! canonicalizedDelayMode)
            parameterValues.emplace_back("delayMode", canonicalDelayMode);

        if (preV10PortableBundle)
        {
            if (! hasCompressorAttack)
            {
                setOrAppendParameter(
                    "compressorAttackMs",
                    1.5f
                        * (2.0f
                           + (1.0f - legacyCompressorDetail)
                               * 28.0f));
            }
            if (! hasCompressorRelease)
            {
                setOrAppendParameter(
                    "compressorReleaseMs",
                    0.7f
                        * (70.0f
                           + legacyCompressorDetail
                               * 260.0f));
            }
        }

        if (legacyDistortionMode && ! hasDedicatedDistortionState)
        {
            setOrAppendParameter(
                "chaosEnabled",
                parameterOrDefault("precisionDriveEnabled", 0.0f));
            setOrAppendParameter("chaosMode", 0.0f);
            setOrAppendParameter(
                "chaosDrive",
                parameterOrDefault("precisionDriveDrive", 0.35f));
            setOrAppendParameter(
                "chaosTone",
                parameterOrDefault("precisionDriveBright", 0.55f));
            setOrAppendParameter("chaosMix", 1.0f);
            setOrAppendParameter("chaosLevelDb", originalPrecisionVolume);
            setOrAppendParameter("precisionDriveEnabled", 0.0f);
        }
        if (preV10PortableBundle
            && std::abs(originalPrecisionVolume) <= 1.0e-6f)
        {
            setOrAppendParameter("precisionDriveVolumeDb", 9.0f);
        }

        parameterValues.erase(
            std::remove_if(
                parameterValues.begin(),
                parameterValues.end(),
                [] (const auto& parameter)
                {
                    return parameter.first == "compressorDetail"
                        || parameter.first == "precisionDriveMode"
                        || parameter.first == "auditionSource"
                        || parameter.first == "preEq100Db"
                        || parameter.first == "preEq200Db"
                        || parameter.first == "preEq400Db"
                        || parameter.first == "preEq800Db"
                        || parameter.first == "preEq1k6Db"
                        || parameter.first == "preEq3k2Db"
                        || parameter.first == "preEq6k4Db";
                }),
            parameterValues.end());
    }

    if (chainType == "instrument")
    {
        if (resourcesRequested)
            return false;

        bool anyApplied = false;
        for (const auto& [id, value] : parameterValues)
            anyApplied = setBuiltInPluginParam(trackId, chainType, fxIndex, id, value) || anyApplied;
        return anyApplied;
    }

    std::shared_ptr<juce::AudioProcessor> processorOwner;
    TrackProcessor* automationTrack = nullptr;
    int masterSlotId = 0;
    if (chainType == "master")
    {
        {
            const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
            if (const auto* slot = findDesiredStageSlot(desiredMasterStageSpec, fxIndex))
                masterSlotId = slot->slotId;
        }

        auto activeStage = std::atomic_load_explicit(&realtimeMasterFXSnapshot, std::memory_order_acquire);
        if (const auto* activeSlot = findActiveStageSlot(activeStage, masterSlotId))
            processorOwner = activeSlot->processor;
    }
    else
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        auto it = trackMap.find(trackId);
        if (it != trackMap.end() && it->second != nullptr)
        {
            automationTrack = it->second;
            if (chainType == "input")
                processorOwner = it->second->getInputFXProcessorShared(fxIndex);
            else if (chainType == "track")
                processorOwner = it->second->getTrackFXProcessorShared(fxIndex);
        }
    }

    auto* processor = processorOwner.get();
    if (processor == nullptr)
        return false;

    auto* rack = dynamic_cast<S13NAMRack*>(processor);
    const bool modelMetadataRequested =
        pedalDeclaredCaptureTypeSpecified || ampDeclaredCaptureTypeSpecified;
    const bool resourcesOrModelMetadataRequested =
        resourcesRequested || modelMetadataRequested;
    if ((resourcesOrModelMetadataRequested
         || dspStateRequested)
        && rack == nullptr)
        return false;

    auto uiStateVar = stateObject->getProperty("uiState");
    const bool uiStateRequested = ! uiStateVar.isVoid();
    if (uiStateRequested && rack != nullptr)
        (void) S13NAMRack::migrateUiStateToCurrent(
            uiStateVar,
            storedEffectsVersion);
    bool scalarOrUiApplied = false;
    const auto publishScalarAndUiState = [&]
    {
        if (rack != nullptr)
        {
            // The internal audition generator is a transient monitor source,
            // never durable project/preset state. Any ordinary state restore
            // returns to live input even if an older bundle carried the field.
            rack->auditionSource.store(0.0f, std::memory_order_relaxed);
            const bool selectorChanged =
                rack->getNAMEffectsDspVersion()
                    != S13NAMRack::currentNAMEffectsDspVersion
                || std::abs(
                       rack->reverbEngineVersion.load(
                           std::memory_order_relaxed)
                       - static_cast<float>(
                           S13NAMRack::currentReverbEngineVersion))
                       > 1.0e-6f;
            rack->namEffectsDspVersion.store(
                S13NAMRack::currentNAMEffectsDspVersion,
                std::memory_order_relaxed);
            rack->reverbEngineVersion.store(
                static_cast<float>(
                    S13NAMRack::currentReverbEngineVersion),
                std::memory_order_relaxed);
            scalarOrUiApplied = selectorChanged
                || dspStateRequested
                || scalarOrUiApplied;
        }

        if (uiStateRequested && rack != nullptr)
        {
            rack->setUiStateJSON(juce::JSON::toString(uiStateVar, false));
            scalarOrUiApplied = true;
        }

        for (const auto& [id, value] : parameterValues)
        {
            // New state carries the durable cabinet request separately from the
            // effective cabEnabled value. Ignore the legacy effective scalar
            // when both are present so an embedded-cab recall cannot erase the
            // user's external-cab preference.
            if (cabRequestedEnabledSpecified && id == "cabEnabled")
                continue;
            scalarOrUiApplied = setBuiltInProcessorParam(processor, id, value) || scalarOrUiApplied;
        }
        if (cabRequestedEnabledSpecified && rack != nullptr)
        {
            rack->setCabRequestedEnabled(requestedCabEnabled);
            scalarOrUiApplied = true;
        }
        if (automationTrack != nullptr)
            automationTrack->invalidatePluginAutomationCache();
    };

    const int latencyBefore = processor->getLatencySamples();
    bool resourcesApplied = false;
    if (resourcesOrModelMetadataRequested)
    {
        const bool applySessionCabAutoBypass = explicitDirectLoadPolicy
            || (! stateObject->hasProperty("values") && ! stateObject->hasProperty("uiState"));
        if (! rack->restoreModelResourceState(pedalPathSpecified,
                                               pedalPath,
                                               ampPathSpecified,
                                               ampPath,
                                               cabPathSpecified,
                                               cabPath,
                                               applySessionCabAutoBypass,
                                               false,
                                               pedalDeclaredCaptureTypeSpecified,
                                               pedalDeclaredCaptureType,
                                               ampDeclaredCaptureTypeSpecified,
                                               ampDeclaredCaptureType,
                                               publishScalarAndUiState,
                                               publicationLeaseFactory,
                                               nullptr,
                                               pedalModelSizeSpecified,
                                               requestedPedalModelSize,
                                               ampModelSizeSpecified,
                                               requestedAmpModelSize))
        {
            return false;
        }
        resourcesApplied = true;
    }
    else
    {
        std::shared_ptr<void> publicationLease;
        if (publicationLeaseFactory)
        {
            publicationLease = publicationLeaseFactory();
            if (! publicationLease)
                return false;
        }
        const juce::ScopedLock processorLock(processor->getCallbackLock());
        publishScalarAndUiState();
    }

    if (processor->getLatencySamples() != latencyBefore)
        recalculatePDC();

    if (chainType == "master" && masterSlotId != 0 && (resourcesApplied || scalarOrUiApplied))
    {
        const auto activeStage =
            std::atomic_load_explicit(
                &realtimeMasterFXSnapshot,
                std::memory_order_acquire);
        if (const auto* activeSlot =
                findActiveStageSlot(
                    activeStage,
                    masterSlotId);
            activeSlot != nullptr
            && activeSlot->processor.get()
                   == processor
            && activeSlot->bypassDelay
                   != nullptr)
        {
            activeSlot->bypassDelay
                ->publishedLatency.store(
                    juce::jmax(
                        0,
                        processor
                            ->getLatencySamples()),
                    std::memory_order_release);
        }
        const auto serializedState = serialiseProcessorStateToBase64(processor);
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        if (auto* slot = findDesiredStageSlot(desiredMasterStageSpec, fxIndex);
            slot != nullptr && slot->slotId == masterSlotId)
        {
            slot->serializedState = serializedState;
        }
    }

    return resourcesApplied || scalarOrUiApplied;
}

bool AudioEngine::setPluginParameter(const juce::String& trackId, int fxIndex, bool isInputFX, int paramIndex, float value)
{
    const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());

    auto it = trackMap.find(trackId);
    if (it == trackMap.end() || !it->second)
        return false;

    auto* track = it->second;
    juce::AudioProcessor* processor = nullptr;

    if (isInputFX)
    {
        if (fxIndex >= 0 && fxIndex < track->getNumInputFX())
            processor = track->getInputFXProcessor(fxIndex);
    }
    else
    {
        if (fxIndex >= 0 && fxIndex < track->getNumTrackFX())
            processor = track->getTrackFXProcessor(fxIndex);
    }

    if (processor == nullptr)
        return false;

    const juce::ScopedLock processorLock(processor->getCallbackLock());
    auto& params = processor->getParameters();
    if (paramIndex < 0 || paramIndex >= params.size() || params[paramIndex] == nullptr)
        return false;

    params[paramIndex]->setValueNotifyingHost(juce::jlimit(0.0f, 1.0f, value));
    return true;
}

bool AudioEngine::removeTrackInputFX(const juce::String& trackId, int fxIndex)
{
    // Retain the processor while its owner and realtime snapshot are updated.
    // Closing the editor remains outside the graph lock because editor teardown
    // must run synchronously on the message thread.
    std::shared_ptr<juce::AudioProcessor> retiringProcessor;
    {
        auto it = trackMap.find(trackId);
        if (it != trackMap.end() && it->second)
        {
            retiringProcessor = it->second->getInputFXProcessorShared(fxIndex);
            if (retiringProcessor)
                pluginWindowManager.closeEditorSync(retiringProcessor.get());
        }
    }

    bool removed = false;
    {
        // The TrackProcessor publishes shared processor snapshots, but an audio
        // callback may already hold the previous one. Quiesce that callback while
        // the snapshot is replaced, then release the retained processor only
        // after it can no longer be processed.
        const juce::ScopedLock audioCallbackGuard (deviceManager.getAudioCallbackLock());
        {
            const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
            auto it = trackMap.find(trackId);
            if (it != trackMap.end() && it->second
                && fxIndex >= 0 && fxIndex < it->second->getNumInputFX()
                && it->second->getInputFXProcessorShared(fxIndex) == retiringProcessor)
            {
                it->second->removeInputFX(fxIndex);
                invalidatePluginABStatesForTrackChain(trackId, true);
                removed = true;
            }
        }
    }

    if (removed && retiringProcessor)
    {
        const juce::ScopedLock processorGuard (retiringProcessor->getCallbackLock());
        retiringProcessor->releaseResources();
    }

    if (removed)
    {
        juce::Logger::writeToLog("AudioEngine: Removed input FX " + juce::String(fxIndex) + " from track " + trackId);
        recalculatePDC();
    }
    return removed;
}

bool AudioEngine::removeTrackFX(const juce::String& trackId, int fxIndex)
{
    std::shared_ptr<juce::AudioProcessor> retiringProcessor;
    bool removingActiveARAProcessor = false;
    {
        auto it = trackMap.find(trackId);
        if (it != trackMap.end() && it->second)
        {
            retiringProcessor = it->second->getTrackFXProcessorShared(fxIndex);
            removingActiveARAProcessor = fxIndex == it->second->getARAFXIndex();
            if (retiringProcessor)
                pluginWindowManager.closeEditorSync(retiringProcessor.get());
        }
    }

    bool removed = false;
    {
        const juce::ScopedLock audioCallbackGuard (deviceManager.getAudioCallbackLock());
        {
            const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
            auto it = trackMap.find(trackId);
            if (it != trackMap.end() && it->second
                && fxIndex >= 0 && fxIndex < it->second->getNumTrackFX()
                && it->second->getTrackFXProcessorShared(fxIndex) == retiringProcessor)
            {
                // The ARA path deactivates the processor before shutting down its
                // document controller. It is now safe because the device callback
                // is quiesced for the complete remove/publish operation.
                it->second->removeTrackFX(fxIndex);
                invalidatePluginABStatesForTrackChain(trackId, false);
                removed = true;
            }
        }
    }

    if (removed && retiringProcessor && !removingActiveARAProcessor)
    {
        const juce::ScopedLock processorGuard (retiringProcessor->getCallbackLock());
        retiringProcessor->releaseResources();
    }

    if (removed)
    {
        juce::Logger::writeToLog("AudioEngine: Removed track FX " + juce::String(fxIndex) + " from track " + trackId);
        recalculatePDC();
    }
    return removed;
}

void AudioEngine::bypassTrackInputFX(const juce::String& trackId, int fxIndex, bool bypassed)
{
    const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
    auto it = trackMap.find(trackId);
    if (it != trackMap.end() && it->second)
    {
        it->second->bypassInputFX(fxIndex, bypassed);
        juce::Logger::writeToLog("AudioEngine: " + juce::String(bypassed ? "Bypassed" : "Unbypassed") +
                               " input FX " + juce::String(fxIndex) + " on track " + trackId);
    }
    recalculatePDC();
}

void AudioEngine::bypassTrackFX(const juce::String& trackId, int fxIndex, bool bypassed)
{
    const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
    auto it = trackMap.find(trackId);
    if (it != trackMap.end() && it->second)
    {
        it->second->bypassTrackFX(fxIndex, bypassed);
        juce::Logger::writeToLog("AudioEngine: " + juce::String(bypassed ? "Bypassed" : "Unbypassed") +
                               " track FX " + juce::String(fxIndex) + " on track " + trackId);
    }
    recalculatePDC();
}

bool AudioEngine::reorderTrackInputFX(const juce::String& trackId, int fromIndex, int toIndex)
{
    const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
    auto it = trackMap.find(trackId);
    if (it == trackMap.end() || !it->second)
        return false;

    bool success = it->second->reorderInputFX(fromIndex, toIndex);
    if (success)
    {
        invalidatePluginABStatesForTrackChain(trackId, true);
        juce::Logger::writeToLog("AudioEngine: Reordered input FX on track " + trackId +
                               " from " + juce::String(fromIndex) + " to " + juce::String(toIndex));
    }
    return success;
}

bool AudioEngine::reorderTrackFX(const juce::String& trackId, int fromIndex, int toIndex)
{
    const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
    auto it = trackMap.find(trackId);
    if (it == trackMap.end() || !it->second)
        return false;

    bool success = it->second->reorderTrackFX(fromIndex, toIndex);
    if (success)
    {
        invalidatePluginABStatesForTrackChain(trackId, false);
        juce::Logger::writeToLog("AudioEngine: Reordered track FX on track " + trackId +
                               " from " + juce::String(fromIndex) + " to " + juce::String(toIndex));
    }
    return success;
}

//==============================================================================
// Master FX Management

bool AudioEngine::addMasterFX(const juce::String& pluginPath)
{
    juce::Logger::writeToLog("AudioEngine: addMasterFX called with: " + pluginPath);

    // Load the plugin with actual device sample rate & block size
    double sr = currentSampleRate > 0 ? currentSampleRate : 44100.0;
    int bs = getSafeHostedPluginBlockSize(currentBlockSize);
    auto plugin = pluginManager.loadPluginFromFile(pluginPath, sr, bs);
    if (!plugin)
    {
        juce::Logger::writeToLog("AudioEngine: Failed to load plugin for master FX");
        return false;
    }

    // Provide tempo/position info to the plugin
    plugin->setPlayHead (this);

    // Plugin was already created at the correct rate by loadPluginFromFile,
    // but re-prepare in case the device has changed since then.
    // Clamp max-block-size to at least 512 (same rationale as track FX).
    auto* device = deviceManager.getCurrentAudioDevice();
    if (device)
    {
        prepareHostedProcessorForPrecision(
            plugin.get(),
            device->getCurrentSampleRate(),
            getSafeHostedPluginBlockSize(device->getCurrentBufferSizeSamples()),
            processingPrecisionMode);
    }

    DesiredFXStageSpec specCopy;
    {
        const juce::ScopedLock lockSl(mainProcessorGraph->getCallbackLock());
        specCopy = desiredMasterStageSpec;
    }

    DesiredFXStageSlot slot;
    slot.slotId = nextMasterStageSlotId++;
    slot.name = plugin->getName();
    if (auto* pluginInstance = dynamic_cast<juce::AudioPluginInstance*>(plugin.get()))
    {
        auto desc = pluginInstance->getPluginDescription();
        slot.type = desc.pluginFormatName == "CLAP" ? "clap" : "vst3";
        slot.pluginPath = desc.createIdentifierString();
        slot.pluginFormat = desc.pluginFormatName;
    }
    else
    {
        slot.type = "plugin";
        slot.pluginPath = pluginPath;
        slot.pluginFormat = "Plugin";
    }
    slot.serializedState = serialiseProcessorStateToBase64(plugin.get());
    specCopy.slots.push_back(std::move(slot));

    if (!publishMasterStageSpec(specCopy))
    {
        juce::Logger::writeToLog("AudioEngine: Failed to publish master stage after adding plugin");
        return false;
    }

    juce::Logger::writeToLog("AudioEngine: Added plugin to master FX chain (total: " + juce::String((int)specCopy.slots.size()) + ")");
    return true;
}

juce::var AudioEngine::getMasterFX()
{
    const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
    juce::Array<juce::var> fxList;
    for (int i = 0; i < static_cast<int>(desiredMasterStageSpec.slots.size()); ++i)
    {
        const auto& slot = desiredMasterStageSpec.slots[static_cast<size_t>(i)];
        juce::DynamicObject::Ptr fxInfo = new juce::DynamicObject();
        fxInfo->setProperty("index", i);
        fxInfo->setProperty("name", slot.name);
        fxInfo->setProperty("bypassed", slot.bypassed);
        fxInfo->setProperty("precisionOverride", slot.forceFloat ? "float32" : "auto");
        fxInfo->setProperty("type", slot.type);
        if (!slot.pluginPath.isEmpty())
            fxInfo->setProperty("pluginPath", slot.pluginPath);
        fxList.add(juce::var(fxInfo.get()));
    }
    return fxList;
}

bool AudioEngine::removeMasterFX(int fxIndex)
{
    DesiredFXStageSpec specCopy;
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        specCopy = desiredMasterStageSpec;
    }

    if (fxIndex < 0 || fxIndex >= static_cast<int>(specCopy.slots.size()))
        return false;

    const int slotId = specCopy.slots[static_cast<size_t>(fxIndex)].slotId;
    const auto retiredStage = std::atomic_load_explicit(&realtimeMasterFXSnapshot, std::memory_order_acquire);
    std::shared_ptr<juce::AudioProcessor> retiringProcessor;
    if (const auto* activeSlot = findActiveStageSlot(retiredStage, slotId))
    {
        retiringProcessor = activeSlot->processor;
        if (retiringProcessor)
            pluginWindowManager.closeEditorSync(retiringProcessor.get());
    }

    syncStageSpecStateFromActive(specCopy, retiredStage);
    specCopy.slots.erase(specCopy.slots.begin() + fxIndex);
    const bool published = publishMasterStageSpec(specCopy);
    if (published)
    {
        // Publication prevents new callbacks from acquiring retiredStage. Taking
        // the device callback lock now drains any callback that retained it before
        // the swap; only then is releaseResources() lifetime-safe.
        {
            const juce::ScopedLock audioCallbackGuard (deviceManager.getAudioCallbackLock());
        }
        if (retiringProcessor)
        {
            const juce::ScopedLock processorGuard (retiringProcessor->getCallbackLock());
            retiringProcessor->releaseResources();
        }
        juce::Logger::writeToLog("AudioEngine: Removed master FX " + juce::String(fxIndex));
    }
    return published;
}

bool AudioEngine::reorderMasterFX(int fromIndex, int toIndex)
{
    DesiredFXStageSpec specCopy;
    std::shared_ptr<const ActiveFXStage> activeStage;
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        specCopy = desiredMasterStageSpec;
        activeStage = std::atomic_load_explicit(
            &realtimeMasterFXSnapshot,
            std::memory_order_acquire);
    }

    const auto slotCount = static_cast<int>(specCopy.slots.size());
    if (fromIndex < 0 || fromIndex >= slotCount
        || toIndex < 0 || toIndex >= slotCount
        || fromIndex == toIndex)
    {
        return false;
    }

    syncStageSpecStateFromActive(specCopy, activeStage);
    auto movedSlot = std::move(specCopy.slots[static_cast<size_t>(fromIndex)]);
    specCopy.slots.erase(specCopy.slots.begin() + fromIndex);
    specCopy.slots.insert(
        specCopy.slots.begin() + toIndex,
        std::move(movedSlot));

    const bool published = publishMasterStageSpec(specCopy);
    if (published)
    {
        juce::Logger::writeToLog(
            "AudioEngine: Reordered master FX from "
            + juce::String(fromIndex)
            + " to "
            + juce::String(toIndex));
    }
    return published;
}

void AudioEngine::openMasterFXEditor(int fxIndex)
{
    int slotId = 0;
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        if (const auto* slot = findDesiredStageSlot(desiredMasterStageSpec, fxIndex))
            slotId = slot->slotId;
    }

    if (slotId == 0)
        return;

    auto activeStage = std::atomic_load_explicit(&realtimeMasterFXSnapshot, std::memory_order_acquire);
    if (const auto* activeSlot = findActiveStageSlot(activeStage, slotId))
    {
        if (activeSlot->processor)
        {
            auto processor = activeSlot->processor;
            auto title = activeSlot->name;
            PluginWindowManager::PluginEditorTarget target;
            target.scope = PluginWindowManager::PluginEditorTarget::Scope::MasterFX;
            target.fxIndex = fxIndex;
            juce::MessageManager::callAsync([this, processor, title, target]()
            {
                if (processor)
                    pluginWindowManager.openEditor(processor, title, target);
            });
        }
    }
}

void AudioEngine::bypassMasterFX(int fxIndex, bool bypassed)
{
    DesiredFXStageSpec specCopy;
    std::shared_ptr<const ActiveFXStage> activeStage;
    int slotId = 0;
    bool wasBypassed = false;
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        specCopy = desiredMasterStageSpec;
        auto* desiredSlot = findDesiredStageSlot(
            specCopy, fxIndex);
        if (desiredSlot == nullptr)
            return;

        slotId = desiredSlot->slotId;
        wasBypassed = desiredSlot->bypassed;
        desiredSlot->bypassed = bypassed;
        activeStage = std::atomic_load_explicit(
            &realtimeMasterFXSnapshot,
            std::memory_order_acquire);
    }

    if (wasBypassed == bypassed)
        return;

    const auto* currentSlot =
        findActiveStageSlot(activeStage, slotId);
    if (currentSlot == nullptr
        || currentSlot->processor == nullptr)
    {
        // A missing active slot indicates an incomplete stage publication.
        // Rebuilding here is a control-thread recovery path, not callback work.
        publishMasterStageSpec(specCopy);
        return;
    }

    if (wasBypassed && ! bypassed)
    {
        // A steady bypass deliberately freezes arbitrary hosted processors to
        // save CPU. Reset under their callback lock before publishing the
        // enable request so stale delay/detector state cannot reappear.
        const juce::ScopedLock processorGuard(
            currentSlot->processor->getCallbackLock());
        currentSlot->processor->reset();
    }

    auto nextStage =
        std::make_shared<ActiveFXStage>(*activeStage);
    if (auto* nextSlot =
            findActiveStageSlot(nextStage, slotId))
    {
        nextSlot->bypassed = bypassed;
    }
    else
    {
        publishMasterStageSpec(specCopy);
        return;
    }

    nextStage->generation =
        masterStageGeneration.fetch_add(
            1, std::memory_order_relaxed) + 1;
    {
        const juce::ScopedLock sl(
            mainProcessorGraph->getCallbackLock());
        desiredMasterStageSpec = specCopy;
        publishRealtimeMasterSnapshot(
            std::static_pointer_cast<const ActiveFXStage>(
                nextStage));
    }

    juce::Logger::writeToLog(
        "AudioEngine: Master FX "
        + juce::String(fxIndex)
        + (bypassed ? " bypassed" : " enabled"));
}

void AudioEngine::setMasterVolume(float volume)
{
    masterVolume.store(
        juce::jlimit(
            0.0f,
            juce::Decibels::decibelsToGain(12.0f),
            volume),
        std::memory_order_relaxed);
    juce::Logger::writeToLog("Master volume set to: " + juce::String(volume));
}

void AudioEngine::setMasterPan(float pan)
{
    const float boundedPan =
        juce::jlimit(-1.0f, 1.0f, pan);
    masterPan.store(
        boundedPan, std::memory_order_release);

    float leftGain = 1.0f;
    float rightGain = 1.0f;
    computePanLawGains(
        currentPanLaw.load(std::memory_order_acquire),
        boundedPan,
        1.0f,
        leftGain,
        rightGain);
    cachedMasterPanL.store(leftGain, std::memory_order_relaxed);
    cachedMasterPanR.store(rightGain, std::memory_order_relaxed);
}

bool AudioEngine::addMonitoringFX(const juce::String& pluginPath)
{
    juce::Logger::writeToLog("AudioEngine: addMonitoringFX called with: " + pluginPath);

    double sr = currentSampleRate > 0 ? currentSampleRate : 44100.0;
    int bs = getSafeHostedPluginBlockSize(currentBlockSize);
    auto plugin = pluginManager.loadPluginFromFile(pluginPath, sr, bs);
    if (!plugin)
    {
        juce::Logger::writeToLog("AudioEngine: Failed to load plugin for monitoring FX");
        return false;
    }

    plugin->setPlayHead(this);

    auto* device = deviceManager.getCurrentAudioDevice();
    if (device)
    {
        prepareHostedProcessorForPrecision(
            plugin.get(),
            device->getCurrentSampleRate(),
            getSafeHostedPluginBlockSize(device->getCurrentBufferSizeSamples()),
            processingPrecisionMode);
    }

    DesiredFXStageSpec specCopy;
    {
        const juce::ScopedLock lockSl(mainProcessorGraph->getCallbackLock());
        specCopy = desiredMonitoringStageSpec;
    }

    DesiredFXStageSlot slot;
    slot.slotId = nextMonitoringStageSlotId++;
    slot.name = plugin->getName();
    if (auto* pluginInstance = dynamic_cast<juce::AudioPluginInstance*>(plugin.get()))
    {
        auto desc = pluginInstance->getPluginDescription();
        slot.type = desc.pluginFormatName == "CLAP" ? "clap" : "vst3";
        slot.pluginPath = desc.createIdentifierString();
        slot.pluginFormat = desc.pluginFormatName;
    }
    else
    {
        slot.type = "plugin";
        slot.pluginPath = pluginPath;
        slot.pluginFormat = "Plugin";
    }
    slot.serializedState = serialiseProcessorStateToBase64(plugin.get());
    specCopy.slots.push_back(std::move(slot));

    if (!publishMonitoringStageSpec(specCopy))
    {
        juce::Logger::writeToLog("AudioEngine: Failed to publish monitoring stage after adding plugin");
        return false;
    }

    juce::Logger::writeToLog("AudioEngine: Added plugin to monitoring FX chain (total: " +
                             juce::String((int)specCopy.slots.size()) + ")");
    return true;
}

juce::var AudioEngine::getMonitoringFX()
{
    const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
    juce::Array<juce::var> fxList;
    for (int i = 0; i < static_cast<int>(desiredMonitoringStageSpec.slots.size()); ++i)
    {
        const auto& slot = desiredMonitoringStageSpec.slots[static_cast<size_t>(i)];
        juce::DynamicObject::Ptr fxInfo = new juce::DynamicObject();
        fxInfo->setProperty("index", i);
        fxInfo->setProperty("name", slot.name);
        fxInfo->setProperty("bypassed", slot.bypassed);
        fxInfo->setProperty("precisionOverride", slot.forceFloat ? "float32" : "auto");
        fxInfo->setProperty("type", slot.type);
        if (!slot.pluginPath.isEmpty())
            fxInfo->setProperty("pluginPath", slot.pluginPath);
        fxList.add(juce::var(fxInfo.get()));
    }
    return fxList;
}

void AudioEngine::removeMonitoringFX(int fxIndex)
{
    DesiredFXStageSpec specCopy;
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        specCopy = desiredMonitoringStageSpec;
    }

    if (fxIndex < 0 || fxIndex >= static_cast<int>(specCopy.slots.size()))
        return;

    const int slotId = specCopy.slots[static_cast<size_t>(fxIndex)].slotId;
    const auto retiredStage = std::atomic_load_explicit(&realtimeMonitoringFXSnapshot, std::memory_order_acquire);
    std::shared_ptr<juce::AudioProcessor> retiringProcessor;
    if (const auto* activeSlot = findActiveStageSlot(retiredStage, slotId))
    {
        retiringProcessor = activeSlot->processor;
        if (retiringProcessor)
            pluginWindowManager.closeEditorSync(retiringProcessor.get());
    }

    syncStageSpecStateFromActive(specCopy, retiredStage);
    specCopy.slots.erase(specCopy.slots.begin() + fxIndex);
    if (publishMonitoringStageSpec(specCopy))
    {
        {
            const juce::ScopedLock audioCallbackGuard (deviceManager.getAudioCallbackLock());
        }
        if (retiringProcessor)
        {
            const juce::ScopedLock processorGuard (retiringProcessor->getCallbackLock());
            retiringProcessor->releaseResources();
        }
        juce::Logger::writeToLog("AudioEngine: Removed monitoring FX " + juce::String(fxIndex));
    }
}

void AudioEngine::openMonitoringFXEditor(int fxIndex)
{
    int slotId = 0;
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        if (const auto* slot = findDesiredStageSlot(desiredMonitoringStageSpec, fxIndex))
            slotId = slot->slotId;
    }

    if (slotId == 0)
        return;

    auto activeStage = std::atomic_load_explicit(&realtimeMonitoringFXSnapshot, std::memory_order_acquire);
    if (const auto* activeSlot = findActiveStageSlot(activeStage, slotId))
    {
        if (activeSlot->processor)
        {
            auto processor = activeSlot->processor;
            auto title = activeSlot->name;
            PluginWindowManager::PluginEditorTarget target;
            target.scope = PluginWindowManager::PluginEditorTarget::Scope::MonitoringFX;
            target.fxIndex = fxIndex;
            juce::MessageManager::callAsync([this, processor, title, target]()
            {
                if (processor)
                    pluginWindowManager.openEditor(processor, title, target);
            });
        }
    }
}

void AudioEngine::bypassMonitoringFX(int fxIndex, bool bypassed)
{
    DesiredFXStageSpec specCopy;
    std::shared_ptr<const ActiveFXStage> activeStage;
    int slotId = 0;
    bool wasBypassed = false;
    {
        const juce::ScopedLock sl(mainProcessorGraph->getCallbackLock());
        specCopy = desiredMonitoringStageSpec;
        auto* desiredSlot = findDesiredStageSlot(
            specCopy, fxIndex);
        if (desiredSlot == nullptr)
            return;

        slotId = desiredSlot->slotId;
        wasBypassed = desiredSlot->bypassed;
        desiredSlot->bypassed = bypassed;
        activeStage = std::atomic_load_explicit(
            &realtimeMonitoringFXSnapshot,
            std::memory_order_acquire);
    }

    if (wasBypassed == bypassed)
        return;

    const auto* currentSlot =
        findActiveStageSlot(activeStage, slotId);
    if (currentSlot == nullptr
        || currentSlot->processor == nullptr)
    {
        publishMonitoringStageSpec(specCopy);
        return;
    }

    if (wasBypassed && ! bypassed)
    {
        const juce::ScopedLock processorGuard(
            currentSlot->processor->getCallbackLock());
        currentSlot->processor->reset();
    }

    auto nextStage =
        std::make_shared<ActiveFXStage>(*activeStage);
    if (auto* nextSlot =
            findActiveStageSlot(nextStage, slotId))
    {
        nextSlot->bypassed = bypassed;
    }
    else
    {
        publishMonitoringStageSpec(specCopy);
        return;
    }

    nextStage->generation =
        monitoringStageGeneration.fetch_add(
            1, std::memory_order_relaxed) + 1;
    {
        const juce::ScopedLock sl(
            mainProcessorGraph->getCallbackLock());
        desiredMonitoringStageSpec = specCopy;
        publishRealtimeMonitoringSnapshot(
            std::static_pointer_cast<const ActiveFXStage>(
                nextStage));
    }

    juce::Logger::writeToLog(
        "AudioEngine: Monitoring FX "
        + juce::String(fxIndex)
        + (bypassed ? " bypassed" : " enabled"));
}

std::vector<AudioRecorder::CompletedRecording> AudioEngine::getLastCompletedClips()
{
    auto clips = lastCompletedClips;
    lastReturnedRecordingClipCount.store(static_cast<int>(clips.size()), std::memory_order_relaxed);
    logAudioRecord("getLastCompletedClips returning count=" + juce::String(static_cast<int>(clips.size())));
    for (const auto& clip : clips)
    {
        logAudioRecord("getLastCompletedClips clip track=" + clip.trackId
            + " file=" + clip.file.getFullPathName()
            + " startTime=" + juce::String(clip.startTime, 3)
            + " duration=" + juce::String(clip.duration, 3));
    }
    lastCompletedClips.clear();  // Clear after reading
    return clips;
}

std::vector<MIDIRecorder::CompletedMIDIRecording> AudioEngine::getLastCompletedMIDIClips()
{
    auto clips = std::move(lastCompletedMIDIClips);
    lastCompletedMIDIClips.clear();
    return clips;
}

juce::var AudioEngine::getActiveRecordingMIDIPreviews(const juce::var& requests)
{
    std::vector<MIDIRecorder::LivePreviewRequest> parsedRequests;

    if (auto* requestArray = requests.getArray())
    {
        parsedRequests.reserve(static_cast<size_t>(requestArray->size()));
        for (const auto& requestVar : *requestArray)
        {
            auto* requestObj = requestVar.getDynamicObject();
            if (requestObj == nullptr)
                continue;

            const juce::String trackId = requestObj->getProperty("trackId").toString();
            if (trackId.isEmpty())
                continue;

            MIDIRecorder::LivePreviewRequest request;
            request.trackId = trackId;
            const auto generationVar = requestObj->getProperty("generation");
            request.generation = generationVar.isVoid()
                ? 0
                : static_cast<uint64_t>(static_cast<int64>(generationVar));
            request.knownEventCount = static_cast<int>(requestObj->getProperty("knownEventCount"));
            parsedRequests.push_back(std::move(request));
        }
    }

    auto snapshots = midiRecorder.getLivePreviewSnapshots(parsedRequests);
    juce::Array<juce::var> snapshotArray;

    for (const auto& snapshot : snapshots)
    {
        auto* snapshotObj = new juce::DynamicObject();
        snapshotObj->setProperty("trackId", snapshot.trackId);
        snapshotObj->setProperty("generation", static_cast<int64>(snapshot.generation));
        snapshotObj->setProperty("recordingStartTime", snapshot.recordingStartTime);
        snapshotObj->setProperty("totalEventCount", snapshot.totalEventCount);

        juce::Array<juce::var> eventsArray;
        for (const auto& evt : snapshot.deltaEvents)
        {
            if (!evt.message.isNoteOn() && !evt.message.isNoteOff())
                continue;

            auto* evtObj = new juce::DynamicObject();
            evtObj->setProperty("timestamp", evt.timestamp);
            evtObj->setProperty("type", evt.message.isNoteOn() ? "noteOn" : "noteOff");
            evtObj->setProperty("note", evt.message.getNoteNumber());
            evtObj->setProperty("velocity", evt.message.isNoteOn() ? evt.message.getVelocity() : 0);
            evtObj->setProperty("channel", evt.message.getChannel());
            eventsArray.add(evtObj);
        }
        snapshotObj->setProperty("deltaEvents", eventsArray);

        juce::Array<juce::var> activeNotesArray;
        for (const auto& activeNote : snapshot.activeNotes)
        {
            auto* activeNoteObj = new juce::DynamicObject();
            activeNoteObj->setProperty("note", activeNote.note);
            activeNoteObj->setProperty("startTimestamp", activeNote.startTimestamp);
            activeNotesArray.add(activeNoteObj);
        }
        snapshotObj->setProperty("activeNotes", activeNotesArray);

        snapshotArray.add(snapshotObj);
    }

    return snapshotArray;
}

